#include <stdio.h>
#include <signal.h>

volatile sig_atomic_t alarms = 0;

void on_alarm(int sig) {
    (void)sig;
    alarms++;
}

int main(void) {
    signal(SIGUSR1, on_alarm);
    raise(SIGUSR1);
    raise(SIGUSR1);
    raise(SIGUSR1);
    printf("caught %d alarms\n", (int)alarms);
    return 0;
}

