#include <stdio.h>
#include <signal.h>

volatile sig_atomic_t usr1 = 0, usr2 = 0;

void on_signal(int sig) {
    if (sig == SIGUSR1) usr1++;
    else if (sig == SIGUSR2) usr2++;
}

int main(void) {
    signal(SIGUSR1, on_signal);
    signal(SIGUSR2, on_signal);
    int which;
    while (scanf("%d", &which) == 1) raise(which == 1 ? SIGUSR1 : SIGUSR2);
    printf("USR1 %d USR2 %d\n", (int)usr1, (int)usr2);
    return 0;
}

