#include <stdio.h>
#include <signal.h>
#include <string.h>

volatile sig_atomic_t interrupts = 0;

void on_interrupt(int sig) {
    (void)sig;
    interrupts++;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_interrupt;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    raise(SIGINT);
    raise(SIGINT);
    signal(SIGINT, SIG_IGN);
    raise(SIGINT);

    printf("interrupts handled: %d\n", (int)interrupts);
    printf("still running\n");
    return 0;
}

