#include <signal.h>

volatile sig_atomic_t handled = 0;

void on_usr1(int sig) {
    (void)sig;
    handled++;
}

int main(void) {
    signal(SIGUSR1, on_usr1);
    sigset_t block;
    sigemptyset(&block);
    sigaddset(&block, SIGUSR1);

    sigprocmask(SIG_BLOCK, &block, NULL);
    raise(SIGUSR1);
    raise(SIGUSR1);
    raise(SIGUSR1);
    printf("while blocked: %d\n", (int)handled);

    sigprocmask(SIG_UNBLOCK, &block, NULL);
    printf("after unblock: %d\n", (int)handled);
    return 0;
}

