#include <stdio.h>
#include <signal.h>
#include <unistd.h>

volatile sig_atomic_t rang = 0;

void on_alarm(int sig) {
    (void)sig;
    rang = 1;
}

int main(void) {
    signal(SIGALRM, on_alarm);
    alarm(1);
    printf("waiting for the alarm...\n");
    pause();
    if (rang) printf("ring! woke up after the alarm\n");
    return 0;
}

